import{z as A,x as B,o,c as d,q as s,j as l,D as E,d as t,s as i,S as n,b as e}from"./chunks/framework.C8m1ZpeB.js";const F=JSON.parse('{"title":"剂量传感闭环","description":"","frontmatter":{"title":"剂量传感闭环","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/dose-sensor-loop.md","filePath":"litho/dose-sensor-loop.md","lastUpdated":1791413859000}'),p={name:"litho/dose-sensor-loop.md"};function m(h,a,D,u,_,T){const r=B("Mermaid");return o(),d("div",null,[a[2]||(a[2]=s('<h1 id="剂量传感闭环" tabindex="-1">剂量传感闭环 <a class="header-anchor" href="#剂量传感闭环" aria-label="Permalink to &quot;剂量传感闭环&quot;">​</a></h1><div class="epigraph"><p>脉冲能量会抖，气体会老。闭环用狭缝附近的能量计把脉冲数和衰减器扣到目标剂量，不是把激光开到最大。</p><footer>—— 对照 [剂量控制](/litho/dose-control)；扫描投影机能量传感器</footer></div><p><a href="/litho/pupil-metrology">上一课</a>校准角谱。缺口是标量：这场要多少 mJ/cm²。主干剂量课写过控制目标；本课写传感器与执行器在机台里怎么环。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>开环按名义 \\(E_p\\times N\\) 会随气体寿命漂。<a href="/litho/pulse-energy-rep-rate">脉冲能量</a> 课已指出抖动。没有现场传感，CDU 的剂量项不可控。传感器脏了或标定错了，闭环会把系统偏差锁死。</p><p><span class="marginnote">闭环可以类比恒温空调：温度计（能量计）不停读数，控制器和设定值比较，再调压缩机（衰减器、脉冲数、扫描速度）。开环则像不看室温、按铭牌功率硬吹——气体老化相当于滤网积灰，实际出力悄悄偏离名义值而没人知道。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>能量计放在照明路径取样位置（部分反射）。执行器：可变衰减、脉冲计数、扫描速度。每场或每扫描带修正。标定用剂量垫或剂量晶圆，把传感器读数接到胶上的有效剂量（含狭缝透过与扫描平均）。</p>',8)),(o(),l(n,null,{default:E(()=>[i(r,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20TGT%5B%22%E7%9B%AE%E6%A0%87%E5%89%82%E9%87%8F%22%5D%20--%3E%20CTRL%5B%22%E6%8E%A7%E5%88%B6%E5%99%A8%22%5D%0A%20%20SNS%5B%22%E8%83%BD%E9%87%8F%E8%AE%A1%22%5D%20--%3E%20CTRL%0A%20%20CTRL%20--%3E%20ATT%5B%22%E8%A1%B0%E5%87%8F%20%2F%20%E8%84%89%E5%86%B2%E6%95%B0%20%2F%20%E9%80%9F%E5%BA%A6%22%5D%0A%20%20ATT%20--%3E%20WAFER%5B%22%E6%99%B6%E5%9C%86%E5%89%82%E9%87%8F%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("p",null,[e("span",{class:"marginnote"},"传感器看到的是照明取样，不是胶里的化学剂量。换胶、换 BARC 不自动改闭环增益；有效剂量要重新标定。")],-1)),a[4]||(a[4]=e("h2",{id:"机制",tabindex:"-1"},[t("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=e("p",null,"反馈把 \\(E_p\\) 慢漂压住。脉冲间高频抖动若快于环带宽，仍进剂量噪声——需要激光自身稳定（上一课序）。扫描速度调制可补偿狭缝向残纹，与均匀性课耦合。",-1)),(o(),l(n,null,{default:E(()=>[i(r,{id:"mermaid-32",class:"mermaid",graph:"flowchart%20LR%0A%20%20SLOW%5B%22Ep%20%E6%85%A2%E6%BC%82%EF%BC%9A%E6%B0%94%E4%BD%93%E8%80%81%E5%8C%96%22%5D%20--%3E%20INB%5B%22%E5%9C%A8%E5%8F%8D%E9%A6%88%E5%B8%A6%E5%AE%BD%E5%86%85%22%5D%20--%3E%20OK%5B%22%E8%A2%AB%E9%97%AD%E7%8E%AF%E5%8E%8B%E4%BD%8F%22%5D%0A%20%20FAST%5B%22%E8%84%89%E5%86%B2%E9%97%B4%E9%AB%98%E9%A2%91%E6%8A%96%E5%8A%A8%22%5D%20--%3E%20OOB%5B%22%E5%BF%AB%E4%BA%8E%E7%8E%AF%E5%B8%A6%E5%AE%BD%22%5D%20--%3E%20LEAK%5B%22%E6%BC%8F%E8%BF%9B%E5%89%82%E9%87%8F%E5%99%AA%E5%A3%B0%22%5D%0A%20%20CAL%5B%22%E4%BC%A0%E6%84%9F%E5%99%A8%E6%A0%87%E5%AE%9A%E5%81%8F%E5%B7%AE%22%5D%20--%3E%20LOCK%5B%22%E8%A2%AB%E9%97%AD%E7%8E%AF%E9%94%81%E6%88%90%E7%B3%BB%E7%BB%9F%E5%81%8F%E5%B7%AE%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=s('<p><span class="marginnote">常见误区：「有了闭环就一定更准」。传感器脏污或标定错时，闭环会忠实地把错误读数稳住，把系统偏差锁死在每一片晶圆上，比开环漂移更隐蔽。所以闭环必须配传感器清洁检查和定期剂量晶圆标定。</span></p><p><span class="marginnote">数字实例：脉冲间 ±5% 的抖动快于环带宽、闭环跟不上，但一场曝光只有几十到几百次脉冲（33 mm 扫描行程除以约 0.5 m/s 扫描速度约 66 ms，乘 5 kHz 只有几百），抖动按 \\(1/\\sqrt{N}\\) 统计平均——100 次脉冲也只把它压到约 \\(5\\%/\\sqrt{100}=0.5\\%\\)。这一部分靠脉冲数量平均掉，剩下的才真正需要激光自身稳定。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>下一课光源功率稳定：激光侧如何少给闭环添乱。传感环不能替代光瞳计。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>剂量闭环 = 能量计 + 衰减/脉冲/速度。</li><li>标定必须接到胶上的有效剂量。</li><li>出处：剂量控制课；扫描机能效通识。</li></ul>',6))])}const c=A(p,[["render",m]]);export{F as __pageData,c as default};
